  z-index: 999;
  overflow: hidden;
}

.dropdown-scroll {
  max-height: v-bind('maxHeight');
  padding: 8px 0;
}

/* 一级分类项样式 */
.dropdown-item {
  display: flex;
  align-items: center;
  min-height: 32px;
  margin-bottom: 4px;
}

.parent-item.selected {
  background-color: #D0EAF8;
  border-radius: 8px;
}

/* 展开图标样式 */
.expand-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  min-width: 24px;
  height: 24px;
  margin-left: 12px;
  margin-right: 8px;
  border-radius: 4px;
}

.expand-placeholder {
  width: 24px;
  min-width: 24px;
  height: 24px;
  margin-left: 12px;
  margin-right: 8px;
}

.expand-icon-img {
  width: 24px;
  height: 24px;
}

/* 一级分类内容区域 */
.item-content {
  padding: 4px 0;
}

.item-text {
  font-size: 14px;
  color: #333;
  line-height: 1.5;
}

/* 二级分类容器 */
