  padding-left: 8px; /* 一级分类图标宽度 + 左边距 + 缩进 */
}

.child-item.selected {
  background-color: #D0EAF8;
  border-radius: 8px;
}

/* 二级分类缩进占位 */
.child-indent-placeholder {
  width: 16px;
  min-width: 16px;
  height: 24px;
  margin-left: 12px;
  margin-right: 8px;
}

/* 一级下拉菜单样式 */
.parent-item.single-level {
  justify-content: center;
}

.parent-item.single-level .item-content {
  width: 100%;
  text-align: center;
}

.parent-item.single-level .item-text {
  text-align: center;
}

.dropdown-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 998;
  background-color: transparent;
}
</style>